        if isempty(centerResp) || strcmpi(centerResp, 'y')
            startRow = floor((gridRows - numMeasureRows) / 2) + 1;
            measureRows = startRow : (startRow + numMeasureRows - 1);
            fprintf('  Auto-centered rows: %s\n', num2str(measureRows));
        else
